#include <bits/stdc++.h>

using namespace std;

int main() {
    int n, c;
    cin >> n >> c;
    int ans = 1, pre;
    cin >> pre;
    for (int i = 1; i < n; i++) {
        int t;
        cin >> t;
        if (t - pre >= c) {
            ++ans;
            pre = t;
        }
    }
    cout << ans << endl;
}
